package io.nebulaflow.engine;
import org.junit.jupiter.api.Test; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
class DagPlannerTest { @Test void topologicallySortsDependencies(){var d=Map.<String,Object>of("steps",List.of(Map.of("id","a","type","NOOP"),Map.of("id","b","type","NOOP","dependsOn",List.of("a")))); assertEquals(List.of("a","b"),DagPlanner.plan(d).stream().map(DagPlanner.Node::id).toList());} @Test void rejectsCycles(){var d=Map.<String,Object>of("steps",List.of(Map.of("id","a","dependsOn",List.of("b")),Map.of("id","b","dependsOn",List.of("a")))); assertThrows(WorkflowValidationException.class,()->DagPlanner.plan(d));} @Test void rejectsMissingDependency(){var d=Map.<String,Object>of("steps",List.of(Map.of("id","a","dependsOn",List.of("missing")))); assertThrows(WorkflowValidationException.class,()->DagPlanner.plan(d));} }
